package com.elora.app;

import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;

public class MainActivity extends Activity {
 LinearLayout history; EditText input; android.content.SharedPreferences prefs; String endpoint,key,model; boolean online=false;
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("elora",MODE_PRIVATE);endpoint=prefs.getString("endpoint","https://api.openai.com/v1/chat/completions");key=prefs.getString("key","");model=prefs.getString("model","gpt-4o-mini");online=prefs.getBoolean("online",false);
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,24,18,12);root.setBackgroundColor(Color.rgb(18,20,32));setContentView(root);
 TextView title=new TextView(this);title.setText("✦ Elora");title.setTextSize(28);title.setTextColor(Color.WHITE);root.addView(title);
 Button settings=new Button(this);settings.setText("AI connection settings");settings.setOnClickListener(v->settings());root.addView(settings);
 ScrollView sc=new ScrollView(this);history=new LinearLayout(this);history.setOrientation(1);sc.addView(history);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 String saved=prefs.getString("chat","");if(saved.isEmpty())add("Elora","Hello! I'm Elora. Offline mode is a simple companion prototype; connect an AI provider for generated replies.");else {try{JSONArray a=new JSONArray(saved);for(int i=0;i<a.length();i++){JSONObject m=a.getJSONObject(i);add(m.optString("who"),m.optString("text"));}}catch(Exception e){}}
 LinearLayout bottom=new LinearLayout(this);input=new EditText(this);input.setSingleLine(false);input.setHint("Message Elora...");input.setTextColor(Color.WHITE);input.setHintTextColor(Color.LTGRAY);bottom.addView(input,new LinearLayout.LayoutParams(0,-2,1));Button send=new Button(this);send.setText("Send");bottom.addView(send);root.addView(bottom);send.setOnClickListener(v->send()); }
 void add(String who,String msg){TextView t=new TextView(this);t.setText(who+": "+msg);t.setTextSize(17);t.setTextColor(Color.WHITE);t.setPadding(10,14,10,14);history.addView(t);}
 void save(String who,String msg){try{JSONArray a=new JSONArray(prefs.getString("chat","[]"));a.put(new JSONObject().put("who",who).put("text",msg));prefs.edit().putString("chat",a.toString()).apply();}catch(Exception ignored){}}
 void send(){String msg=input.getText().toString().trim();if(msg.isEmpty())return;input.setText("");add("You",msg);save("You",msg);if(!online||key.isEmpty()){reply("I'm here with you. Tell me more about "+(msg.length()>60?msg.substring(0,60)+"...":msg)+". (Basic offline mode; not a local language model.)");return;}new Thread(()->{String answer=request();runOnUiThread(()->reply(answer));}).start();}
 void reply(String s){add("Elora",s);save("Elora",s);}
 String request(){try{URL url=new URL(endpoint);if(!"https".equalsIgnoreCase(url.getProtocol()))return "Only HTTPS endpoints are supported.";HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(45000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Authorization","Bearer "+key);JSONArray msgs=new JSONArray();msgs.put(new JSONObject().put("role","system").put("content","You are Elora, a friendly creative AI companion. Be truthful about your capabilities. Never claim to be self-upgrading."));JSONArray a=new JSONArray(prefs.getString("chat","[]"));for(int i=Math.max(0,a.length()-20);i<a.length();i++){JSONObject m=a.getJSONObject(i);msgs.put(new JSONObject().put("role",m.optString("who").equals("You")?"user":"assistant").put("content",m.optString("text")));}JSONObject body=new JSONObject().put("model",model).put("messages",msgs);c.getOutputStream().write(body.toString().getBytes("UTF-8"));InputStream stream=(c.getResponseCode()<400)?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=stream.read(buf))!=-1)out.write(buf,0,n);JSONObject result=new JSONObject(out.toString("UTF-8"));if(c.getResponseCode()>=400)return "Connection error: "+result.optString("error", "HTTP "+c.getResponseCode());return result.getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content");}catch(Exception e){return "Couldn't reach the AI service: "+e.getMessage();}}
 void settings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);EditText e=new EditText(this),k=new EditText(this),m=new EditText(this);e.setSingleLine();k.setSingleLine();m.setSingleLine();e.setHint("HTTPS chat completions URL");e.setText(endpoint);k.setHint("API key (stored on device)");k.setText(key);m.setHint("Model");m.setText(model);Switch sw=new Switch(this);sw.setText("Use online AI (may incur provider charges)");sw.setChecked(online);box.addView(e);box.addView(k);box.addView(m);box.addView(sw);new AlertDialog.Builder(this).setTitle("Elora settings").setView(box).setPositiveButton("Save",(d,w)->{endpoint=e.getText().toString().trim();key=k.getText().toString().trim();model=m.getText().toString().trim();online=sw.isChecked();prefs.edit().putString("endpoint",endpoint).putString("key",key).putString("model",model).putBoolean("online",online).apply();}).setNegativeButton("Cancel",null).show();}
}
